package local.starccm.assistant;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import star.base.neo.*;
import star.cadmodeler.*;
import star.common.*;

/** Typed native 3D-CAD operations for an explicitly selected, unassociated working model.
 * Original files and existing CAD Parts are never replaced. No model-supplied Java is executed.
 * The dispatcher owns source-path authorization, checkpoints, state tokens and final saving.
 */
public final class NativeGeometryRepair {
    private NativeGeometryRepair() { }
    public static final Set<String> TYPES=Set.of("import_cad_model","repair_cad_model");
    private static final Set<String> IMPORT_KEYS=Set.of("type","id","expected_state","reason","path","name");
    private static final Set<String> REPAIR_KEYS=Set.of("type","id","expected_state","reason","body_ids","remove_sheet_body_ids","planar_axis","planar_tolerance_m","sew_tolerance_m","fill_holes","unite","allow_open_result");
    public static boolean supports(String type){return TYPES.contains(type);}
    public static String contract(){return "import_cad_model: id=simulation_actions,path=用户明确给出的原始本机STEP/IGES绝对路径,name=唯一派生模型名。原生3D-CAD导入包含sheet bodies；保留已有源CAD Parts和原文件，返回实际model/body IDs与native_bounds。repair_cad_model: id=真实派生CadModel ID,body_ids=[该模型全部当前body IDs],remove_sheet_body_ids=[明确诊断须重建的平面sheet body IDs，可为空],planar_axis=x/y/z与planar_tolerance_m在移除非空时必须给出,sew_tolerance_m=明确SI公差,fill_holes=true/false,unite=true/false。可选allow_open_result=true仅用于分阶段缝合诊断；仍开放时保存中间工作模型并返回geometry_ready=false，禁止据此划网格；unite须false。默认false严格要求全部solid。只允许尚无关联Parts、无编辑中特征的工作模型；不会编辑已关联源CAD部件。移除候选逐项核验sheet且整个body的native bbox在所选轴厚度≤公差；只在此工作模型删除这些候选，随后原生Sew(convertToSolid)、可选FillHoles和Unite。端盖由剩余孔边重建，不能声称原端盖未改变；禁止合成新飞机或隐藏几何变化。执行后每个现存body须是真实非空CAD solid，且unite=true须恰好一体，才报告完成；失败保留部分特征和收据。检查模型时一次inspect该CadModel即可取得全部body IDs、solid标记和native_extent_m，无需逐体重复查询。不能把未闭合sheet直接create_parts_from_cad当作可计算实体。对于彼此接触的原始曲面，应先根据实际包围盒与闭合诊断选择明确坏平面端盖；remove_sheet_body_ids为空表示不删除任何面。移除非空只可依据已测得厚度和几何问题，不能为凑实体随意删面。该动作一次执行Sew→FillHoles→Unite；成功后重新inspect确认实际实体。随后使用create_parts_from_cad创建关联实体部件，继续外域/网格；此动作本身不生成网格或运行CFD。";}
    private static void require(boolean ok,String message)throws IOException{if(!ok)throw new IOException(message);}
    private static double positive(Map<?,?> a,String key)throws IOException{Object x=a.get(key);require(x instanceof Number&&Double.isFinite(((Number)x).doubleValue())&&((Number)x).doubleValue()>0,key+"必须明确给出有限正数(SI)");return ((Number)x).doubleValue();}
    private static void flush(Simulation s){s.getServer().getClientNotifyHandler().processCommandQueue(true);}
    private static List<String> ids(Collection<? extends ClientServerObject> values){List<String> out=new ArrayList<>();for(ClientServerObject o:values)out.add(o.getObjectKeyAsString());return out;}
    private static double[] bounds(CadModel m,Body b)throws IOException{DoubleVector v=m.getSelectedBounds(List.of(b));require(v.size()==6,"原生CAD包围盒未返回6个坐标");double[] out=v.toDoubleArray();for(double x:out)require(Double.isFinite(x),"原生CAD包围盒包含非有限值");return out;}
    private static Map<String,Object> body(CadModel m,Body b)throws IOException{double[] v=bounds(m,b);Map<String,Object> row=new LinkedHashMap<>();row.put("id",b.getObjectKeyAsString());row.put("name",b.getPresentationName());row.put("solid",b.isSolid());row.put("mesh_body",b.isMeshBody());row.put("empty",b.isEmpty());row.put("face_count",b.getFaceManager().getFaces().size());row.put("native_min_m",List.of(v[0],v[2],v[4]));row.put("native_max_m",List.of(v[1],v[3],v[5]));row.put("native_extent_m",List.of(v[1]-v[0],v[3]-v[2],v[5]-v[4]));NeoProperty stats=b.getStatistics();row.put("native_measure_type",b.isSolid()?"volume_m3":"surface_area_m2");row.put("native_measure",stats.get("Amount"));row.put("native_centroid",String.valueOf(stats.get("CenterOfGravity")));return row;}
    public static Map<String,Object> describe(Simulation s,ClientServerObject target){Map<String,Object> out=new LinkedHashMap<>();try{if(target instanceof Body)out.put("native_cad_geometry",body(((Body)target).getModel(),(Body)target));else if(target instanceof CadModel){CadModel m=(CadModel)target;List<Map<String,Object>> rows=new ArrayList<>();for(Body b:m.getBodyManager().getBodies())rows.add(body(m,b));out.put("native_cad_geometry",rows);out.put("native_repair_action","repair_cad_model");}else if(target==s)out.put("native_geometry_actions",new TreeSet<>(TYPES));}catch(Exception e){out.put("native_geometry_read_error",String.valueOf(e.getMessage()));}return out;}
    private static CadModel model(Simulation s,ClientServerObject target)throws IOException{require(target instanceof CadModel,"repair_cad_model需要真实CadModel目标");CadModel m=(CadModel)target;require(m.getSimulation()==s&&CadPartCreation.objects(s).get(m.getObjectKeyAsString())==m,"工作CAD模型不属于当前SIM");return m;}
    private static List<Body> selection(CadModel m,Object raw,String key,boolean empty)throws IOException{require(raw instanceof List&&(empty||!((List<?>)raw).isEmpty()),key+"必须明确给出实际Body ID列表");Map<String,Body> current=new LinkedHashMap<>();for(Body b:m.getBodyManager().getBodies())current.put(b.getObjectKeyAsString(),b);List<Body> out=new ArrayList<>();Set<Object> seen=new HashSet<>();for(Object id:(List<?>)raw){require(id instanceof String&&seen.add(id)&&current.containsKey(id),key+"存在重复、过期或非本模型Body ID: "+id);out.add(current.get(id));}return out;}
    public static void validate(Simulation s,Map<?,?> a,ClientServerObject target)throws Exception{String type=String.valueOf(a.get("type"));require(supports(type),"未知原生CAD操作");Set<String> keys=type.equals("import_cad_model")?IMPORT_KEYS:REPAIR_KEYS;for(Object key:a.keySet())require(keys.contains(key),"原生CAD动作不接受参数: "+key);
        if(type.equals("import_cad_model")){require(target==s,"import_cad_model必须以当前simulation_actions为目标");Path p=Path.of(String.valueOf(a.get("path")));String path=p.toString().toLowerCase(Locale.ROOT);require(p.isAbsolute()&&Files.isRegularFile(p)&&Files.isReadable(p)&&(path.endsWith(".step")||path.endsWith(".stp")||path.endsWith(".iges")||path.endsWith(".igs")),"原生CAD导入需要可读本机STEP/IGES绝对路径");Object name=a.get("name");require(name instanceof String&&name.toString().matches("[\\p{L}_][\\p{L}\\p{N}_ .-]{0,79}"),"派生CAD模型名称无效");if(s.has(SolidModelManager.class)!=null)for(CadModelBase m:s.get(SolidModelManager.class).getObjects())require(!m.getPresentationName().equals(name),"CAD模型同名，未重复导入");return;}
        CadModel m=model(s,target);require(m.isUptoDate()&&!m.getFeatureManager().isAnyFeatureInEditMode(),"工作CAD模型必须已更新且无正在编辑的特征");for(GeometryPart p:s.get(SimulationPartManager.class).getLeafParts())if(p instanceof SolidModelPart)require(!m.equals(((SolidModelPart)p).getCadModel()),"工作模型已有关联CAD Parts；先选择独立派生模型，未编辑源部件");
        List<Body> selected=selection(m,a.get("body_ids"),"body_ids",false);require(new HashSet<>(selected).equals(new HashSet<>(m.getBodyManager().getBodies())),"修复要求明确列出工作模型全部当前body IDs，不能隐式波及未选择对象");for(Body b:selected)require(!b.isMeshBody()&&!b.isEmpty(),"仅支持非空真实CAD body，不能混入faceted/mesh body");positive(a,"sew_tolerance_m");require(a.get("fill_holes") instanceof Boolean&&a.get("unite") instanceof Boolean,"必须明确给出fill_holes和unite布尔值");require(!a.containsKey("allow_open_result")||a.get("allow_open_result") instanceof Boolean,"allow_open_result必须为布尔值");require(!Boolean.TRUE.equals(a.get("allow_open_result"))||!Boolean.TRUE.equals(a.get("unite")),"分阶段开放结果不能同时要求实体合并");List<Body> remove=selection(m,a.get("remove_sheet_body_ids"),"remove_sheet_body_ids",true);require(remove.size()<selected.size(),"不能删除工作模型全部几何");if(!remove.isEmpty()){String axis=String.valueOf(a.get("planar_axis"));require(axis.matches("[xyz]"),"移除端盖须明确planar_axis=x/y/z");int k="xyz".indexOf(axis);double tolerance=positive(a,"planar_tolerance_m");for(Body b:remove){require(!b.isSolid()&&!b.getFaceManager().getFaces().isEmpty(),"仅允许明确选择的平面sheet端盖，不能删除实体；所有面必须整体通过平面bbox检查");double[] v=bounds(m,b);require(v[2*k+1]-v[2*k]<=tolerance,"待重建面体未通过原生平面厚度核验: "+b.getObjectKeyAsString());}}
    }
    public static final class GeometryException extends IOException{private final Map<String,Object> receipt;GeometryException(String message,Throwable cause,Map<String,Object> receipt){super(message,cause);this.receipt=new LinkedHashMap<>(receipt);}public Map<String,Object> receipt(){return new LinkedHashMap<>(receipt);}}
    private static void feature(Simulation s,CadModel m,Feature f,List<Map<String,Object>> steps)throws Exception{Map<String,Object> row=new LinkedHashMap<>();row.put("feature_id",f.getObjectKeyAsString());row.put("feature_type",f.getClass().getName());steps.add(row);boolean executed=m.getFeatureManager().execute(f);flush(s);row.put("executed",executed);row.put("valid",f.isValid());row.put("execution_status",String.valueOf(f.getExecutionStatus()));row.put("error",f.getErrorMessage());require(executed&&f.isValid(),"原生特征执行未通过: "+f.getPresentationName()+" "+f.getErrorMessage());}
    public static Map<String,Object> execute(Simulation s,Map<?,?> a,ClientServerObject target)throws Exception{validate(s,a,target);Map<String,Object> out=new LinkedHashMap<>();List<Map<String,Object>> steps=new ArrayList<>();out.put("steps",steps);out.put("source_cad_file_modified",false);out.put("existing_cad_parts_modified",false);CadModel m=null;try{if(String.valueOf(a.get("type")).equals("import_cad_model")){m=s.get(SolidModelManager.class).createSolidModel();m.setPresentationName(String.valueOf(a.get("name")));out.put("created_model_id",m.getObjectKeyAsString());out.put("source_path",String.valueOf(a.get("path")));ImportCadFileFeature imported=m.importCadFile(String.valueOf(a.get("path")),true);flush(s);Map<String,Object> row=new LinkedHashMap<>();row.put("feature_id",imported.getObjectKeyAsString());row.put("valid",imported.isValid());row.put("execution_status",String.valueOf(imported.getExecutionStatus()));row.put("error",imported.getErrorMessage());steps.add(row);require(imported.isValid()&&!m.getBodyManager().getBodies().isEmpty(),"原生CAD导入未得到任何可检查body；isValid不能单独证明导入成功");out.put("working_cad_model_modified",false);}else{m=model(s,target);out.put("before",describe(s,m));List<Body> remove=selection(m,a.get("remove_sheet_body_ids"),"remove_sheet_body_ids",true);List<Map<String,Object>> deleted=new ArrayList<>();for(Body b:remove)deleted.add(body(m,b));out.put("removed_sheet_bodies",deleted);if(!remove.isEmpty()){DeleteBodyFeature deletion=m.getFeatureManager().createDeleteBody(remove);deletion.setPresentationName("Rebuild_explicit_planar_caps");feature(s,m,deletion,steps);}Units metre=(Units)s.getUnitsManager().getObject("m");SewSheetBodiesFeature sew=m.getFeatureManager().createSewSheetBodiesFeature();sew.setPresentationName("Sew_original_surfaces");sew.setBodies(new ArrayList<>(m.getBodyManager().getBodies()));sew.getTolerance().setValueAndUnits(positive(a,"sew_tolerance_m"),metre);sew.setConvertToSolid(true);sew.setSewIndependently(false);feature(s,m,sew,steps);if(Boolean.TRUE.equals(a.get("fill_holes"))){FillHolesFeature fill=m.getFeatureManager().createFillHolesFeature(new ArrayList<>(m.getBodyManager().getBodies()));fill.setPresentationName("Fill_existing_boundary_loops");fill.setConvertToSolid(true);fill.setRemoveRedundantEdges(true);feature(s,m,fill,steps);}if(!Boolean.TRUE.equals(a.get("allow_open_result")))for(Body b:m.getBodyManager().getBodies())require(b.isSolid()&&!b.isMeshBody()&&!b.isEmpty(),"修复后仍存在开放或非CAD实体，未宣称几何完成: "+b.getObjectKeyAsString());if(Boolean.TRUE.equals(a.get("unite"))&&m.getBodyManager().getBodies().size()>1){UniteBodiesFeature unite=m.getFeatureManager().createUniteBodies(new ArrayList<>(m.getBodyManager().getBodies()));unite.setPresentationName("Unite_repaired_source_bodies");unite.setKeepImprintedEdges(true);unite.getTolerance().setValueAndUnits(positive(a,"sew_tolerance_m"),metre);feature(s,m,unite,steps);}require(!m.getBodyManager().getBodies().isEmpty(),"修复后无body");if(Boolean.TRUE.equals(a.get("unite")))require(m.getBodyManager().getBodies().size()==1,"原生合并未形成唯一机体；不能创建单体外流场");if(!Boolean.TRUE.equals(a.get("allow_open_result")))for(Body b:m.getBodyManager().getBodies())require(b.isSolid()&&!b.isMeshBody()&&!b.isEmpty(),"最终输出不是非空真实CAD solid");out.put("working_cad_model_modified",true);out.put("cad_changes_disclosed",!remove.isEmpty()?"Only explicitly selected planar sheet bodies removed; original retained surfaces sewn within stated tolerance; holes capped from remaining boundary loops; optional native unite.":"Native sewing, optional filling of remaining boundary loops and optional unite; all executed features listed.");}flush(s);s.get(SolidModelManager.class).endEditCadModel(m);out.put("model_id",m.getObjectKeyAsString());out.put("body_ids",ids(m.getBodyManager().getBodies()));out.put("actual",describe(s,m));boolean ready=!m.getBodyManager().getBodies().isEmpty();for(Body b:m.getBodyManager().getBodies())ready&=b.isSolid()&&!b.isEmpty()&&!b.isMeshBody();out.put("geometry_ready",ready);out.put("modified",true);out.put("complete",true);out.put("validation","Native CAD bodies read back; no mesh or CFD executed. create_parts_from_cad and independent mesh/geometry checks remain required.");return out;}catch(Exception e){out.put("complete",false);out.put("error",String.valueOf(e.getMessage()));if(m!=null){out.put("model_id",m.getObjectKeyAsString());out.put("actual",describe(s,m));}throw new GeometryException("原生CAD操作未完成，保留实际特征和部分结果收据: "+e.getMessage(),e,out);}}
}
